let _markdown = "\n\n> <FeedbackBlock id=\"be25cd8554614cc6\" body=\"Make sure to read their Metadata section for the fundamentals of Metadata API.\">\n>   Make sure to read their [Metadata section](https://nextjs.org/docs/app/building-your-application/optimizing/metadata) for the fundamentals of Metadata API.\n> </FeedbackBlock>\n\nMetadata Image [#metadata-image]\n\n<FeedbackBlock id=\"ca19632660675d41\" body=\"You can generate metadata images dynamically using next/og.\">\n  You can generate metadata images dynamically using `next/og`.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"716f4b6ebdee44e5\" body=\"Add the following under your loader, and define image metadata for pages:\">\n  Add the following under your loader, and define image metadata for pages:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"lib/source.ts\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"lib/source.ts\">\n      lib/source.ts\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"app/docs/[[...slug]]/page.tsx\">\n      app/docs/[[...slug]]/page.tsx\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"lib/source.ts\">\n    ```ts\n    import { type InferPageType } from 'fumadocs-core/source';\n\n    // [!code ++:8]\n    export function getPageImage(page: InferPageType<typeof source>) {\n      const segments = [...page.slugs, 'image.png'];\n\n      return {\n        segments,\n        url: `/og/docs/${segments.join('/')}`,\n      };\n    }\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"app/docs/[[...slug]]/page.tsx\">\n    ```tsx\n    import { notFound } from 'next/navigation';\n    import { source, getPageImage } from '@/lib/source';\n    import type { Metadata } from 'next';\n\n    export async function generateMetadata(props: PageProps<'/docs/[[...slug]]'>): Promise<Metadata> {\n      const params = await props.params;\n      const page = source.getPage(params.slug);\n      if (!page) notFound();\n\n      return {\n        title: page.data.title,\n        description: page.data.description,\n        openGraph: {\n          // [!code ++]\n          images: getPageImage(page).url,\n        },\n      };\n    }\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n> <FeedbackBlock id=\"4af99dd4e285f849\" body=\"We append image.png to the end of slugs so that we can access it via /og/docs/my-page/image.png.\">\n>   We append `image.png` to the end of slugs so that we can access it via `/og/docs/my-page/image.png`.\n> </FeedbackBlock>\n\n<FeedbackBlock id=\"b9fb5de5fa108452\" body=\"Finally, create a route handler to generate images at build time:\">\n  Finally, create a route handler to generate images at build time:\n</FeedbackBlock>\n\n```tsx title=\"app/og/docs/[...slug]/route.tsx\"\n// Example code removed - see Fumadocs documentation for OG image setup\n```\n\n<FeedbackBlock id=\"2f7f8398866f6e03\" body=\"You can specify options for Satori (used by next/og), see https://github.com/vercel/satori for reference.\">\n  You can specify options for Satori (used by `next/og`), see [https://github.com/vercel/satori](https://github.com/vercel/satori) for reference.\n</FeedbackBlock>\n\nOther Presets [#other-presets]\n\n<FeedbackBlock id=\"5f230c787972436a\" body=\"There's other available styles on Fumadocs CLI, such as mono:\">\n  There's other available styles on Fumadocs CLI, such as `mono`:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npx @fumadocs/cli@latest add og/mono\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm dlx @fumadocs/cli@latest add og/mono\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn dlx @fumadocs/cli@latest add og/mono\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun x @fumadocs/cli@latest add og/mono\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"3dedd536211aa9ee\" body=\"Replace your old generate with the installed one.\">\n  Replace your old `generate` with the installed one.\n</FeedbackBlock>\n";
